    expect(collides(base[0], base[1])).toBe(false);
    expect(collides(base[0], base[2])).toBe(false);
    expect(collides(base[0], { i: 'z', x: 3, y: 1, w: 2, h: 2 })).toBe(true);
    expect(collides(base[0], base[0])).toBe(false);
  });
});

