    expect(result.find((i) => i.i === 'c')).toMatchObject({ x: 0, y: 0 });
    expect(result.find((i) => i.i === 'a')!.y).toBe(2);
    expect(result.find((i) => i.i === 'b')!.y).toBe(2);
